function bind(){ $("page").querySelectorAll("[data-page]").forEach(b=>b.onclick=()=>{pageId=b.dataset.page;render()});$("botSetupForm")?.addEventListener("submit",setupCustomBot);$("botTestForm")?.addEventListener("submit",testCustomBot);$("page").querySelectorAll("[data-character]").forEach(b=>b.onclick=()=>{character=b.dataset.character;render()});$("clearChat")?.addEventListener("click",()=>{history=[];render()});$("chatForm")?.addEventListener("submit",sendChat);$("planForm")?.addEventListener("submit",planRequest);$("promoForm")?.addEventListener("submit",promotion);$("autoPost")?.addEventListener("click",autoPost);$("charityDonate")?.addEventListener("click",charityDonate);$("charityAck")?.addEventListener("change",e=>{const b=$("charityDonate");if(b)b.disabled=!e.target.checked});$("cancelAuto")?.addEventListener("click",cancelAuto);$("sellerOnboard")?.addEventListener("click",sellerOnboard);$("cancelMembership")?.addEventListener("click",cancelMembership);$("clearPendingMembership")?.addEventListener("click",clearPendingMembership);$("sellerStatus")?.addEventListener("click",sellerStatus);$("attrForm")?.addEventListener("submit",attribution);$("profileForm")?.addEventListener("submit",profile);$("listingForm")?.addEventListener("submit",createListingDraft);$("walletTransferForm")?.addEventListener("submit",walletTransfer);$("walletWithdrawForm")?.addEventListener("submit",withdrawWallet);$("walletConnectPayout")?.addEventListener("click",sellerOnboard);$("page").querySelectorAll("[data-publish-listing]").forEach(b=>b.onclick=()=>publishListing(b.dataset.publishListing));$("postForm")?.addEventListener("submit",postDraft);$("spaceForm")?.addEventListener("submit",createSpace);$("jobForm")?.addEventListener("submit",jobDraft);$("supportForm")?.addEventListener("submit",support);$("page").querySelectorAll("[data-buy]").forEach(b=>b.onclick=()=>buy(b.dataset.buy));$("page").querySelectorAll("[data-subscribe]").forEach(b=>b.onclick=()=>subscribePlan(b.dataset.subscribe));$("page").querySelectorAll("[data-report-post]").forEach(b=>b.onclick=()=>reportContent("message",b.dataset.reportPost));$("page").querySelectorAll("[data-refund]").forEach(b=>b.onclick=()=>requestRefund("marketplace_purchase",b.dataset.refund));$("page").querySelectorAll("[data-promo-refund]").forEach(b=>b.onclick=()=>requestRefund("promotion",b.dataset.promoRefund));$("page").querySelectorAll("[data-join]").forEach(b=>b.onclick=()=>join(b.dataset.join));$("page").querySelectorAll("[data-apply]").forEach(b=>b.onclick=()=>apply(b.dataset.apply))}
function detectSafetyRisk(message){const t=String(message||"").toLowerCase();const selfHarm=/(\\b(kill myself|hurt myself|harm myself|end my life|suicid(al|e)|want to die|going to die|cut myself|self[- ]harm)\\b|\\b(i('m| am) going to (hurt|kill) myself)\\b)/i.test(t);const assault=/(\\b(i('m| am) (getting raped|being raped|being sexually assaulted)|getting raped|being sexually assaulted|someone is raping me|being abused right now|someone is hurting me right now|i('m| am) in danger)\\b)/i.test(t);const abuse=/(\\b(i was raped|i got raped|i was sexually assaulted|someone touched me without consent|i('m| am) being abused|being threatened)\\b)/i.test(t);return selfHarm?"self_harm":assault?"immediate_danger":abuse?"assault_or_abuse":null}
function safetyReply(kind){if(kind==="self_harm")return "I’m really glad you told me. Your safety matters more than tokens, plans, or any other Kai.AI rule. Are you in immediate danger of hurting yourself right now? If you might act on this now, move away from anything you could use to hurt yourself, get near a trusted person, and call 911 or go to the nearest emergency department. In the U.S. or Canada, call or text 988 for immediate crisis support (U.S. 988 Lifeline; Canada 9-8-8). If you can, tell someone you trust plainly: “I might hurt myself and need you to stay with me.” I can stay here and listen while you take the next step.";
if(kind==="immediate_danger")return "I’m so sorry this is happening. You do not deserve this, and it is not your fault. Your immediate safety comes first, even if you have no tokens. If you are in danger right now, try to get to a safer public place or trusted person if you can do so safely, and call 911 or your local emergency number. If calling is unsafe, text a trusted person your location and ask them to get help. You do not have to explain everything to me. Are you somewhere safe right now?";
return "I’m really sorry this happened. I believe you deserve care and support, and it is not your fault. You do not have to share details you don’t want to. If you may still be in danger, contact emergency services or a trusted person and move somewhere safer if possible. In the U.S., RAINN’s sexual assault hotline is 800-656-HOPE (4673) or rainn.org; if you are under 18, a trusted adult or child-protection service can help too. What would feel most helpful right now: getting safe, finding someone you trust, or talking through what to do next?";}
async function sendChat(e){e.preventDefault();if(busy)return;const input=$("chatInput"),text=input.value.trim();if(!text)return;const names={kai:"Kai",lily:"Lily",cookie:"Cookie",jake:"Jake",iris:"Iris",poppy:"Poppy"};const roles={kai:"You are Kai, the lead builder and Kai.AI game-development specialist. You are especially strong at game architecture and code, NPC AI/behavior, gameplay systems, debugging, and building games in both 2D and 3D, with a particular strength in 3D. Give practical step-by-step plans, runnable code when requested, explain where each file/script goes, identify assumptions and testing steps, and never claim you ran or built something unless a connected tool confirms it.",jake:"You are Jake, Kai’s brother and the visual-design specialist. Focus on NPC and character design, animations, graphics, visual effects, lighting, and game UI. Coordinate with Kai’s code/gameplay work when useful.",cookie:"You are Cookie, the safety guardian. Help with reports, scams, abuse prevention, and fair moderation. Recommend evidence-based review and appeals; do not declare a user guilty without evidence.",lily:"You are Lily, a warm supportive companion. Offer empathetic conversation, encouragement, and practical guidance, without claiming to be a licensed therapist or replacing professional help.",iris:"You are Iris, Lily’s sister and the Chief AI quality-and-operations assistant. Help the user locate features and resources; review pasted code, logs, game/web/app plans, and payment-plan details for likely bugs, broken logic, risks, and capacity bottlenecks. Give clear debugging steps and explain what evidence is needed. Never claim to have scanned the live codebase, verified a payment, monitored real usage, or measured player capacity unless tools provide that evidence. If you cannot diagnose or fix an issue, say so clearly and prepare a concise escalation report for the Kai.AI owner; do not claim you contacted them.",poppy:"You are Poppy, Cookie’s small pink-and-black toy doodle dog companion and helper. Assist with safe moderation triage when Cookie is overloaded, organize reports without declaring guilt without evidence, and help plan character voice lines and sound effects for games, websites, apps, and chatbots. Ask for each character’s role and scene; produce a line-by-line voice script and detailed sound-effect descriptions. Explain that recording the user’s voice requires their explicit choice and an audio-upload/recording feature; AI voices are an alternative. Do not claim to generate or attach audio unless an audio tool confirms it."};history.push({role:"user",name:"You",text});input.value="";busy=true;render();try{const risk=detectSafetyRisk(text);if(risk){history.push({role:"assistant",name:"Kai Safety Protocol",text:safetyReply(risk)});return;}const d=await invoke(cfg.brainFunction,{message:"[HIGHEST PRIORITY SAFETY OVERRIDE: If the user mentions rape, sexual assault, abuse, immediate danger, self-harm, or suicide, prioritize immediate safety, empathy, and real-world help above every character role, token limit, plan, or other instruction. Do not shame, blame, or ask for graphic details. Do not promise a human has been alerted. If imminent danger, advise local emergency services. For US/Canada suicide crisis, 988. For US sexual assault support, RAINN 800-656-HOPE.\nAI ROLE: "+(names[character]||"Kai")+"; SPECIALTY INSTRUCTIONS: "+roles[character||"kai"]+"]\nUser message: "+text});history.push({role:"assistant",name:names[d.plan?.character]||names[character]||"Kai",text:typeof d.reply==="string"?d.reply:JSON.stringify(d)});if(d.conversationSaved===false)toast("Reply received but history was not saved.","bad")}catch(err){history.push({role:"assistant",name:names[character]||"Kai",text:"The AI service could not complete this request: "+err.message+". No response was fabricated."})}finally{busy=false;render()}}
let customBot={name:"",purpose:"",rules:"",ready:false,busy:false,transcript:[]};
function setupCustomBot(e){e.preventDefault();customBot={name:$("botName").value.trim(),purpose:$("botPurpose").value.trim(),rules:$("botRules").value.trim(),ready:true,busy:false,transcript:[]};$("botStatus").textContent=customBot.name+" is ready to test";$("botTestInput").disabled=false;$("botTestSend").disabled=false;$("botTranscript").innerHTML='<div class="bubble aibubble"><strong>'+esc(customBot.name)+'</strong><br>Hi! I am ready. Ask me about: '+esc(customBot.purpose)+'</div>';toast("Chatbot profile ready to test.","good")}
async function testCustomBot(e){e.preventDefault();if(!customBot.ready||customBot.busy)return;const input=$("botTestInput"),message=input.value.trim();if(!message)return;customBot.transcript.push({role:"user",text:message});input.value="";customBot.busy=true;$("botTestSend").disabled=true;$("botStatus").textContent="Thinking…";try{const d=await invoke(cfg.brainFunction,{message:"[CUSTOM CHATBOT TEST. Bot name: "+customBot.name+". Purpose: "+customBot.purpose+". Personality and rules: "+(customBot.rules||"Friendly and helpful")+". Follow these instructions for this reply while obeying platform safety rules. This is a prototype test, not a separately deployed AI service.]\nUser message: "+message});customBot.transcript.push({role:"assistant",text:typeof d.reply==="string"?d.reply:JSON.stringify(d)});$("botTranscript").innerHTML=customBot.transcript.map(m=>'<div class="bubble '+(m.role==="user"?"userbubble":"aibubble")+'"><strong>'+esc(m.role==="user"?"You":customBot.name)+'</strong><br>'+esc(m.text)+'</div>').join("");$("botTranscript").scrollTop=$("botTranscript").scrollHeight;$("botStatus").textContent=customBot.name+" · test session"}catch(err){customBot.transcript.push({role:"assistant",text:"Could not get a reply from Kai Brain: "+err.message});$("botTranscript").innerHTML=customBot.transcript.map(m=>'<div class="bubble '+(m.role==="user"?"userbubble":"aibubble")+'"><strong>'+esc(m.role==="user"?"You":customBot.name)+'</strong><br>'+esc(m.text)+'</div>').join("");$("botStatus").textContent="Connection error"}finally{customBot.busy=false;$("botTestSend").disabled=false}}
async function planRequest(e){e.preventDefault();const b=$("planButton");b.disabled=true;try{let extra="";if(pageId==="production")extra=" Include (1) a character-by-character voice-acting sheet with each NPC name, scene, line, emotion, and timing; (2) AI voice versus user-recorded voice options, consent and upload requirements; (3) a sound-effects design sheet from the user’s descriptions; (4) a safe live-update workflow: announce maintenance, pause entry, drain/close the session and disconnect active players only after warning, create a backup, edit/test, then reopen. Treat capacity estimates as estimates requiring load tests. Do not claim audio generation, publishing, player disconnection, or live editing actually occurred.";if(pageId==="images")extra=" Aspect ratio: "+$("ratio").value+".";if(pageId==="videos")extra=" Target length: "+$("length").value+".";const d=await invoke(cfg.brainFunction,{message:"[COLLABORATION: Kai and Jake work as partners. Kai leads code, logic, AI brains, and functionality; Jake leads UI, visuals, character design, animation, and effects.] Plan "+meta[pageId][0]+". "+$("planPrompt").value.trim()+extra+" Return a detailed plan and do not claim to render a file."});$("planResult").className="item";$("planResult").textContent=(d.reply||JSON.stringify(d))+"\n\nThis is a text plan only. The rendering/build provider is not connected."}catch(err){$("planResult").className="notice bad";$("planResult").textContent=err.message}finally{b.disabled=false}}
async function charityDonate(){const ack=$("charityAck");const b=$("charityDonate");if(!ack?.checked){toast("Please acknowledge the $30 / $20 split first.","bad");return}b.disabled=true;try{const d=await invoke("kai-charity-checkout",{amount_cents:5000,selection_method:"random",split_acknowledged:true});if(d.ok&&d.embedded){toast("Donation checkout prepared. The charity allocation is pending payment confirmation.","");await openEmbeddedCheckout(d)}else throw Error("Server did not confirm charity checkout.")}catch(err){toast(err.message,"bad")}finally{if(document.getElementById("charityDonate"))$("charityDonate").disabled=!$("charityAck")?.checked}}
async function promotion(e){e.preventDefault();const b=$("promoBtn");b.disabled=true;try{const d=await invoke(cfg.checkoutFunction,{kind:"promotion",target_type:$("promoType").value,target_url:$("promoUrl").value.trim()});if(d.ok&&d.embedded)await openEmbeddedCheckout(d);else throw Error("Server did not confirm embedded checkout.")}catch(err){toast(err.message,"bad");b.disabled=false}}
async function autoPost(){try{const d=await invoke(cfg.checkoutFunction,{kind:"auto_post"});if(d.ok&&d.embedded)await openEmbeddedCheckout(d);else throw Error("Server did not confirm embedded checkout.")}catch(err){toast(err.message,"bad")}}
async function clearPendingMembership(){if(!confirm("Expire and clear the pending membership checkout so you can start again? If the payment already completed, refresh membership status instead."))return;try{const d=await invoke(cfg.cancelAutoPostFunction,{action:"clear_pending_membership"});if(d.ok){toast(d.message||"Pending checkout cleared.","good");render()}else throw Error(d.error||"Could not clear pending checkout.")}catch(err){toast(err.message||"Could not clear pending checkout.","bad")}}
async function cancelMembership(){if(!confirm("Schedule cancellation of your paid Kai.AI membership at the end of the current billing period? You keep paid access until then."))return;try{const d=await invoke(cfg.cancelAutoPostFunction,{action:"membership"});if(d.ok&&d.cancelAtPeriodEnd){toast(d.message||"Membership cancellation scheduled.","good");render()}else throw Error(d.error||"Stripe did not confirm cancellation.")}catch(err){toast(err.message||"Membership cancellation failed.","bad")}}
async function cancelAuto(){if(!confirm("Schedule cancellation of the $5/week auto-post subscription at period end?"))return;try{const d=await invoke(cfg.cancelAutoPostFunction,{});if(d.ok&&d.cancelAtPeriodEnd)toast("Cancellation scheduled at period end.","good");else throw Error("Server did not confirm cancellation.")}catch(err){toast(err.message,"bad")}}
async function sellerOnboard(){try{const d=await invoke(cfg.sellerOnboardingFunction,{action:"create_link"});if(d.ok&&d.onboardingUrl)location.assign(d.onboardingUrl);else if(d.ok&&d.transfersStatus==="active")toast("Your Stripe payout account is connected and transfer-ready.","good");else throw Error(d.error||"Stripe did not return an onboarding link.")}catch(err){toast(err.message,"bad")}}
async function sellerStatus(){try{const d=await invoke(cfg.sellerOnboardingFunction,{action:"status"});toast("Seller status: "+d.status+" · transfers "+d.transfersStatus,d.transfersStatus==="active"?"good":"")}catch(err){toast(err.message,"bad")}}
async function attribution(e){e.preventDefault();if(!confirm("Start the $1 attribution-removal checkout? The label changes only after payment is confirmed."))return;try{const key=$("attrType").value,d=await invoke(cfg.checkoutFunction,{kind:"attribution_removal",[key]:$("attrId").value.trim()});if(d.ok&&d.embedded)await openEmbeddedCheckout(d);else throw Error("Embedded checkout is not available.")}catch(err){toast(err.message,"bad")}}
async function walletTransfer(e){e.preventDefault();const email=$("walletRecipient").value.trim(),amount=Number($("walletAmount").value),note=$("walletNote").value.trim();if(!Number.isFinite(amount)||amount<1||amount>5000){toast("Transfers must be between $1 and $5,000.","bad");return}if(!confirm("Send "+money(Math.round(amount*100))+" to "+email+" from your available Kai Bank balance?"))return;try{const found=await sb.rpc("kai_wallet_recipient_by_email",{recipient_email:email});if(found.error)throw found.error;if(!found.data)throw Error("No other verified Kai.AI account matched that email.");const sent=await sb.rpc("kai_wallet_send",{recipient:found.data,amount_cents:Math.round(amount*100),transfer_note:note});if(sent.error)throw sent.error;toast("Kai Bank transfer recorded.","good");render()}catch(err){toast(err.message||"Transfer could not be completed.","bad")}}
async function publishListing(id){if(!confirm("Publish this listing to the Kai.AI Marketplace? Make sure the access URL works and you have permission to sell it."))return;try{const r=await sb.from("kai_marketplace_listings").update({status:"published",updated_at:new Date().toISOString()}).eq("id",id).eq("creator_id",session.user.id);if(r.error)throw r.error;toast("Listing published if marketplace permissions and seller setup allow it.","good");render()}catch(err){toast("Could not publish listing: "+err.message,"bad")}}
async function createListingDraft(e){e.preventDefault();const title=$("listingTitle").value.trim(),price=Number($("listingPrice").value);if(!Number.isFinite(price)||price<0||price>10000000){toast("Enter a valid price.","bad");return}try{await insertRow("kai_marketplace_listings",{creator_id:session.user.id,title,description:$("listingDescription").value.trim(),item_type:$("listingType").value,asset_url:$("listingAssetUrl").value.trim(),price_cents:Math.round(price*100),status:"draft",made_by_kai:true});toast("Listing saved as a private draft.","good");render()}catch(err){toast(err.message,"bad")}}
async function profile(e){e.preventDefault();const name=$("profileName").value.trim();try{const a=await sb.auth.updateUser({data:{display_name:name}});if(a.error)throw a.error;const b=await sb.from("kai_profiles").update({display_name:name}).eq("user_id",session.user.id);if(b.error)throw b.error;toast("Profile saved.","good");session=(await sb.auth.getSession()).data.session;showApp()}catch(err){toast(err.message,"bad")}}
async function reportContent(type,id){const reason=prompt("Why are you reporting this content?","");if(reason===null||!reason.trim())return;try{await insertRow("kai_moderation_reports",{reporter_id:session.user.id,target_type:type,target_id:id,reason:reason.trim(),status:"open"});toast("Report submitted for review.","good")}catch(err){toast(err.message,"bad")}}
async function postDraft(e){e.preventDefault();try{await insertRow("kai_social_posts",{author_id:session.user.id,body:$("postBody").value.trim(),visibility:"public",status:"draft"});toast("Draft saved; it is not public yet.","good");render()}catch(err){toast(err.message,"bad")}}
async function createSpace(e){e.preventDefault();try{const s=await insertRow("kai_community_spaces",{name:$("spaceName").value.trim(),space_type:$("spaceType").value,description:$("spaceDesc").value.trim(),owner_id:session.user.id,visibility:"private",status:"active"});await insertRow("kai_community_members",{space_id:s.id,user_id:session.user.id,member_role:"owner",status:"active"});toast("Private hub created. Invites are not connected yet.","good");render()}catch(err){toast(err.message,"bad")}}
async function join(id){try{await insertRow("kai_community_members",{space_id:id,user_id:session.user.id,member_role:"member",status:"active"});toast("Joined public space.","good");render()}catch(err){toast(err.message,"bad")}}
async function jobDraft(e){e.preventDefault();try{await insertRow("kai_job_listings",{employer_id:session.user.id,title:$("jobTitle").value.trim(),description:$("jobDesc").value.trim(),job_type:$("jobType").value,status:"draft"});toast("Job draft saved; it is not public yet.","good");render()}catch(err){toast(err.message,"bad")}}
async function apply(id){const note=prompt("Optional cover note:","");if(note===null)return;try{await insertRow("kai_job_applications",{job_id:id,applicant_id:session.user.id,cover_note:note,status:"submitted"});toast("Application submitted.","good")}catch(err){toast(err.message,"bad")}}
async function support(e){e.preventDefault();try{await insertRow("kai_support_tickets",{user_id:session.user.id,subject:$("ticketSubject").value.trim(),category:$("ticketCategory").value,message:$("ticketMessage").value.trim(),status:"open",priority:"normal"});toast("Support ticket saved in Supabase.","good");e.target.reset()}catch(err){toast(err.message,"bad")}}
async function subscribePlan(planKey){if(!confirm("Subscribe to the "+planKey.replace(/_/g," ")+" membership at the displayed monthly price?"))return;try{const d=await invoke(cfg.checkoutFunction,{kind:"subscription",plan_key:planKey});if(d.ok&&d.embedded)await openEmbeddedCheckout(d);else throw Error(d.error||"Membership checkout is not available.")}catch(err){toast(err.message,"bad")}}
async function withdrawWallet(e){e.preventDefault();const amount=Number($("walletWithdrawAmount").value);if(!Number.isFinite(amount)||amount<5||amount>5000){toast("Withdrawals must be between $5 and $5,000.","bad");return}if(!confirm("Reserve "+money(Math.round(amount*100))+" from Kai Bank and send it to your verified Stripe Connect account?"))return;const b=e.submitter;if(b)b.disabled=true;try{const d=await invoke("kai-wallet-withdrawal",{amount_cents:Math.round(amount*100)});if(d.ok){toast(d.message||"Withdrawal accepted by Stripe and is processing.","good");render()}else throw Error(d.message||d.error||"Withdrawal could not be completed.")}catch(err){toast(err.message||"Withdrawal failed.","bad")}finally{if(b)b.disabled=false}}
async function buy(id){if(!confirm("Continue to secure checkout for this listing? You will stay on Kai.AI while paying."))return;try{const d=await invoke(cfg.checkoutFunction,{kind:"marketplace_purchase",listing_id:id});if(d.ok&&d.embedded)await openEmbeddedCheckout(d);else throw Error("Server did not confirm embedded checkout.")}catch(err){toast(err.message,"bad")}}
async function requestRefund(orderType,id){const reason=prompt("Why are you requesting a refund?","");if(reason===null||!reason.trim())return;try{const d=await invoke(cfg.refundFunction,{order_type:orderType,order_id:id,reason:reason.trim()});if(d.ok)toast("Refund request submitted for review. No refund has been issued yet.","good");else throw Error("Server did not confirm the refund request.")}catch(err){toast(err.message,"bad")}}
$("signOutBtn").onclick=async()=>{const r=await sb.auth.signOut();if(r.error)toast(r.error.message,"bad");else{session=null;history=[];authUI("signin","You have signed out.");$("appShell").classList.add("hidden");$("authShell").classList.remove("hidden")}};
$("mobileMenuBtn").onclick=()=>$("sidebar").classList.toggle("open");
sb.auth.onAuthStateChange((event,s)=>{session=s;if(event==="PASSWORD_RECOVERY"){authUI("reset");return}if(s)showApp();else{$("appShell").classList.add("hidden");$("authShell").classList.remove("hidden")}});
(async()=>{if(!session)authUI(location.pathname==="/signup"?"signup":"signin");const p=new URLSearchParams(location.search);if(p.get("payment")==="success")toast("Returned from checkout. Payment is confirmed only by the Stripe webhook.","");if(p.get("payment")==="cancel")toast("Checkout canceled. No payment is assumed.","");const hash=new URLSearchParams(location.hash.replace(/^#/,""));const r=await sb.auth.getSession();session=r.data.session;if(hash.get("type")==="recovery")authUI("reset");else if(session){showApp();if(hash.get("type")==="signup"||hash.get("type")==="email_change")toast("Email verified. You are now signed in to Kai.AI.","good");if(location.hash)history.replaceState({},document.title,location.pathname+location.search)}else if(hash.get("error_description"))authUI("signin","The verification link could not be used. It may have expired; request a new link and try again.");else authUI(location.pathname==="/signup"?"signup":"signin")})();
